posts.body:
I just created one using a paralell event.
Explain:
Your orb picture's id is 99, so it always displays on top.
Picture 51-70 are used to display trails (after images, whatever you call it).
The event checks if picture #99 is available, and spawn a trail picture every 4 frames, then fadeout the picture in 30 frame.
Code:
◆Script：if(!window.findTrailSlot){
：      ：function findTrailSlot(){
：      ：  for(var i=51;i<=70;i++){
：      ：    if(!$gameScreen.picture(i)){
：      ：      return i;
：      ：    }
：      ：  }
：      ：  return -1;
：      ：}
：      ：window.findTrailSlot = findTrailSlot;
：      ：}
◆Script：if(!window.clearTrails){
：      ：function clearTrails(){
：      ：  var pp = $gameScreen.picture(99);
：      ：  for(var i=51;i<=70;i++){
：      ：    var p = $gameScreen.picture(i);
：      ：    if(!pp || (p && p._opacity==0)){
：      ：      $gameScreen.erasePicture(i)
：      ：    }
：      ：  }
：      ：}
：      ：window.clearTrails = clearTrails;
：      ：}
◆Script：clearTrails();
◆Control Variables：#0001 i += 1
◆Control Variables：#0002 j = i
◆Control Variables：#0002 j %= 4
◆If：j = 0
  ◆If：Script：$gameScreen.picture(99)
    ◆Script：var t = findTrailSlot();
    ：      ：var p = $gameScreen.picture(99);
    ：      ：if(t>0){
    ：      ：  $gameScreen.showPicture(t, p._name, p._origin, p._x, p._y, p._scaleX, p._scaleY, p._opacity/2, p._blendMode);
    ：      ：  $gameScreen.movePicture(t, p._origin, p._x, p._y, p._scaleX, p._scaleY, 0, p._blendMode, 30, p._easingType);
    ：      ：}
    ◆
  ：End
  ◆
：End
